/** The rules whose conditions together imply one more fact. */
const BETA_RULES: readonly (readonly [string, string])[] = [
  ['even positive !prime', 'composite'],
  ['!composite positive !prime', '!even'],
  ['integer !odd', 'even'],
  ['!extended_positive extended_real !zero', 'extended_negative'],
  ['extended_nonpositive extended_nonzero', 'extended_negative'],
  ['!extended_negative extended_real', 'extended_nonnegative'],
  ['!extended_positive extended_real', 'extended_nonpositive'],
  ['extended_real !zero', 'extended_nonzero'],
  ['!extended_negative extended_real !zero', 'extended_positive'],
  ['extended_nonnegative extended_nonzero', 'extended_positive'],
  ['!infinite !real', '!extended_real'],
  ['!extended_negative !extended_positive !zero', '!extended_real'],
  ['extended_real !real', 'infinite'],
  ['!rational real', 'irrational'],
  ['!positive real !zero', 'negative'],
  ['nonpositive nonzero', 'negative'],
  ['extended_negative finite', 'negative'],
  ['extended_real !integer', 'noninteger'],
  ['!negative real', 'nonnegative'],
  ['extended_nonnegative finite', 'nonnegative'],
  ['!positive real', 'nonpositive'],
  ['extended_nonpositive finite', 'nonpositive'],
  ['extended_nonzero finite', 'nonzero'],
  ['!even integer', 'odd'],
  ['!composite even !prime', '!positive'],
  ['!negative real !zero', 'positive'],
  ['nonnegative nonzero', 'positive'],
  ['extended_positive finite', 'positive'],
  ['!composite even positive', 'prime'],
  ['!negative !positive !zero', '!real'],
  ['extended_real !infinite', 'real'],
  ['extended_real finite', 'real'],
  ['!algebraic complex', 'transcendental'],
  ['!extended_negative !extended_positive extended_real', 'zero'],
  ['!negative !positive real', 'zero'],
  ['extended_nonnegative extended_nonpositive', 'zero'],
  ['nonnegative nonpositive', 'zero'],
];

const parse = (lit: string): [string, boolean] => (lit.startsWith('!') ? [lit.slice(1), false] : [lit, true]);
const literals = (s: string): [string, boolean][] => s.split(' ').filter(Boolean).map(parse);
const lit = (k: string, v: boolean): string => (v ? k : `!${k}`);

/**
 * SymPy `FactKB.deduce_all_facts` of a new knowledge base: the given facts
 * and all their consequences, in a map from the fact name to its value.
 * Contradicting facts throw a RangeError (SymPy InconsistentAssumptions, a ValueError).
 */
export function deduceAllFacts(facts: Readonly<Record<string, boolean>>): Map<string, boolean> {
  const kb = new Map<string, boolean>();
  const tell = (k: string, v: boolean): boolean => {
    const old = kb.get(k);
    if (old === undefined) {
      kb.set(k, v);
      return true;
    }
    if (old !== v) throw new RangeError(`inconsistent assumptions: ${k}=${String(v)} contradicts ${k}=${String(old)}`);
    return false;
  };
  let pending: [string, boolean][] = Object.entries(facts);
  while (pending.length) {
    for (const [k, v] of pending) {
      if (!tell(k, v)) continue;
      for (const [k2, v2] of literals(FULL_IMPLICATIONS[lit(k, v)] ?? '')) tell(k2, v2);
    }
    pending = BETA_RULES.filter(([cond, impl]) => {
      const [k, v] = parse(impl);
      return kb.get(k) !== v && literals(cond).every(([ck, cv]) => kb.get(ck) === cv);
    }).map(([, impl]) => parse(impl));
  }
  return kb;
}
